import{az as t,P as a,Q as n,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const D=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/base/HTTP.md","filePath":"server/base/HTTP.md","lastUpdated":1785339991000}'),e={name:"server/base/HTTP.md"};function p(o,s,r,c,d,i){return a(),n("div",null,[...s[0]||(s[0]=[l(`<h2 id="http-https-协议" tabindex="-1">HTTP/HTTPS 协议 <a class="header-anchor" href="#http-https-协议" aria-label="Permalink to “HTTP/HTTPS 协议”">​</a></h2><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP" target="_blank" rel="noreferrer">MDN HTTP</a></p><p>HTTP（HyperText Transfer Protocol）是 Web 通信的基础协议，采用客户端-服务器模型，基于请求-响应机制。HTTPS 是在 HTTP 与 TCP 之间加入 TLS/SSL 加密层的安全版本，保证数据传输的机密性与完整性。</p><h2 id="http-请求方法" tabindex="-1">HTTP 请求方法 <a class="header-anchor" href="#http-请求方法" aria-label="Permalink to “HTTP 请求方法”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>用途</th><th>幂等</th><th>安全</th></tr></thead><tbody><tr><td>GET</td><td>获取资源</td><td>是</td><td>是</td></tr><tr><td>POST</td><td>创建资源</td><td>否</td><td>否</td></tr><tr><td>PUT</td><td>更新整个资源</td><td>是</td><td>否</td></tr><tr><td>PATCH</td><td>局部更新资源</td><td>否</td><td>否</td></tr><tr><td>DELETE</td><td>删除资源</td><td>是</td><td>否</td></tr><tr><td>HEAD</td><td>获取响应头</td><td>是</td><td>是</td></tr><tr><td>OPTIONS</td><td>预检请求</td><td>是</td><td>是</td></tr></tbody></table><div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">GET</span><span style="color:#BABED8;"> /api/users/1 </span><span style="color:#F78C6C;">HTTP</span><span style="color:#BABED8;">/</span><span style="color:#F78C6C;">1.1</span></span>
<span class="line"><span style="color:#F07178;">Host</span><span style="color:#F78C6C;">:</span><span style="color:#C3E88D;"> example.com</span></span>
<span class="line"><span style="color:#F07178;">Accept</span><span style="color:#F78C6C;">:</span><span style="color:#C3E88D;"> application/json</span></span>
<span class="line"><span style="color:#F07178;">Authorization</span><span style="color:#F78C6C;">:</span><span style="color:#C3E88D;"> Bearer eyJhbGc...</span></span></code></pre></div><h2 id="http-状态码" tabindex="-1">HTTP 状态码 <a class="header-anchor" href="#http-状态码" aria-label="Permalink to “HTTP 状态码”">​</a></h2><p>状态码用三位数字表示请求结果，按首位分类。</p><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>常见状态码</th></tr></thead><tbody><tr><td>1xx</td><td>信息性</td><td>101 Switching Protocols</td></tr><tr><td>2xx</td><td>成功</td><td>200 OK、201 Created、204 No Content</td></tr><tr><td>3xx</td><td>重定向</td><td>301 Moved、302 Found、304 Not Modified</td></tr><tr><td>4xx</td><td>客户端错误</td><td>400 Bad Request、401 Unauthorized、403 Forbidden、404 Not Found</td></tr><tr><td>5xx</td><td>服务器错误</td><td>500 Internal Error、502 Bad Gateway、503 Service Unavailable</td></tr></tbody></table><h2 id="http-请求与响应结构" tabindex="-1">HTTP 请求与响应结构 <a class="header-anchor" href="#http-请求与响应结构" aria-label="Permalink to “HTTP 请求与响应结构”">​</a></h2><div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 请求</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">POST</span><span style="color:#BABED8;"> /api/users </span><span style="color:#F78C6C;">HTTP</span><span style="color:#BABED8;">/</span><span style="color:#F78C6C;">1.1</span></span>
<span class="line"><span style="color:#F07178;">Host</span><span style="color:#F78C6C;">:</span><span style="color:#C3E88D;"> api.example.com</span></span>
<span class="line"><span style="color:#F07178;">Content-Type</span><span style="color:#F78C6C;">:</span><span style="color:#C3E88D;"> application/json</span></span>
<span class="line"><span style="color:#F07178;">Content-Length</span><span style="color:#F78C6C;">:</span><span style="color:#C3E88D;"> 42</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">{</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;">name</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">Alice</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C792EA;">email</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">a@b.com</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;"># 响应</span></span>
<span class="line"><span style="color:#BABED8;">HTTP/</span><span style="color:#F78C6C;">1.1</span><span style="color:#F78C6C;"> 201</span><span style="color:#BABED8;"> Created</span></span>
<span class="line"><span style="color:#BABED8;">Content-Type: application/json</span></span>
<span class="line"><span style="color:#BABED8;">Location: /api/users/</span><span style="color:#F78C6C;">101</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">{</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C792EA;">id</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 101</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C792EA;">name</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">Alice</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">}</span></span></code></pre></div><h2 id="https-加密流程" tabindex="-1">HTTPS 加密流程 <a class="header-anchor" href="#https-加密流程" aria-label="Permalink to “HTTPS 加密流程”">​</a></h2><p>HTTPS 通过 TLS 协议实现加密通信，核心流程包括证书验证与密钥协商。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># HTTPS 连接建立流程</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. ClientHello：客户端发送支持的 TLS 版本与加密套件</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. ServerHello：服务器选择加密套件，返回证书</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 证书验证：客户端校验证书合法性（CA 签名、有效期、域名）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 密钥交换：通过非对称加密协商出对称密钥</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 5. 加密通信：双方使用对称密钥加密数据</span></span></code></pre></div><table tabindex="0"><thead><tr><th>阶段</th><th>加密方式</th><th>目的</th></tr></thead><tbody><tr><td>证书验证</td><td>非对称（RSA/ECDSA）</td><td>身份认证</td></tr><tr><td>密钥协商</td><td>非对称（ECDHE）</td><td>安全交换密钥</td></tr><tr><td>数据传输</td><td>对称（AES）</td><td>高效加密数据</td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 使用 curl 查看 TLS 握手过程</span></span>
<span class="line"><span style="color:#FFCB6B;">curl</span><span style="color:#C3E88D;"> -v</span><span style="color:#C3E88D;"> https://example.com</span><span style="color:#89DDFF;"> 2&gt;&amp;1</span><span style="color:#89DDFF;"> |</span><span style="color:#FFCB6B;"> grep</span><span style="color:#C3E88D;"> -E</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">SSL|TLS|certificate</span><span style="color:#89DDFF;">&#39;</span></span></code></pre></div><h2 id="http-版本演进" tabindex="-1">HTTP 版本演进 <a class="header-anchor" href="#http-版本演进" aria-label="Permalink to “HTTP 版本演进”">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>传输方式</th><th>特性</th></tr></thead><tbody><tr><td>HTTP/1.0</td><td>短连接</td><td>每次请求新建 TCP 连接</td></tr><tr><td>HTTP/1.1</td><td>长连接</td><td>Keep-Alive 复用连接、管道化</td></tr><tr><td>HTTP/2</td><td>多路复用</td><td>二进制分帧、头部压缩、服务端推送</td></tr><tr><td>HTTP/3</td><td>QUIC（UDP）</td><td>解决队头阻塞、0-RTT 连接</td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 启用 HTTP/2（Nginx 配置）</span></span>
<span class="line"><span style="color:#FFCB6B;">server</span><span style="color:#C3E88D;"> {</span></span>
<span class="line"><span style="color:#FFCB6B;">    listen</span><span style="color:#F78C6C;"> 443</span><span style="color:#C3E88D;"> ssl</span><span style="color:#C3E88D;"> http2</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#FFCB6B;">    ssl_certificate</span><span style="color:#C3E88D;">     /path/to/cert.pem</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#FFCB6B;">    ssl_certificate_key</span><span style="color:#C3E88D;"> /path/to/key.pem</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span></code></pre></div><p>HTTPS 是现代 Web 的标配。通过 TLS 加密与证书认证，既保护了用户数据不被窃听篡改，也验证了服务器身份。HTTP/2 与 HTTP/3 在安全基础上进一步优化了传输性能。</p>`,20)])])}const F=t(e,[["render",p]]);export{D as __pageData,F as default};
